def _filter_users(users, predicate):
    out = []
    for u in users:
        if predicate(u):
            out.append({'id': u['id'], 'name': u['name'], 'email': u['email']})
    return out

def get_active_user(users):
    return _filter_users(users, lambda u: u['status'] == 'active')

def get_admin_user(users):
    return _filter_users(users, lambda u: u['role'] == 'admin')
```

